def longest_path(n, edges):
    # Build adjacency list
    adj = [[] for _ in range(n + 1)]
    for a, b in edges:
        adj[a].append(b)
        adj[b].append(a)

    # DP: dp[mask][u] = length of longest path ending at u with nodes in mask
    # mask is a bitmask of used nodes
    # We'll use a dictionary for efficiency
    dp = {}

    # Initialize: single node paths
    for u in range(1, n + 1):
        dp[(1 << u), u] = 1

    max_len = 1

    # Try all masks
    for mask in range(1, 1 << (n + 1)):
        for u in range(1, n + 1):
            if not (mask & (1 << u)):
                continue

            # Current path length
            current_len = dp.get((mask, u), 0)
            if current_len == 0:
                continue

            max_len = max(max_len, current_len)

            # Try to extend the path
            for v in adj[u]:
                if mask & (1 << v):
                    continue

                # Create new mask
                new_mask = mask | (1 << v)

                # Update DP
                new_len = current_len + 1
                if (new_mask, v) not in dp or dp[(new_mask, v)] < new_len:
                    dp[(new_mask, v)] = new_len

    return max_len

# Read input
import sys

for line in sys.stdin:
    n = int(line.strip())
    if n == 0:
        break

    edges = []
    for _ in range(n):
        a, b = map(int, sys.stdin.readline().strip().split())
        edges.append((a, b))

    result = longest_path(n, edges)
    print(result)
"}

