import sys

def solve():
    t = int(sys.stdin.readline())
    for _ in range(t):
        # Place queen at (1, 1)
        print("1 1")
        sys.stdout.flush()

        queen_x, queen_y = 1, 1

        # King's position (we'll track it)
        king_x, king_y = 8, 8  # Start with a guess

        for move_num in range(130):
            # Determine king's new position based on direction
            direction = sys.stdin.readline().strip()

            if direction == "Done":
                break

            if direction == "Right":
                king_y += 1
            elif direction == "Left":
                king_y -= 1
            elif direction == "Up":
                king_x -= 1
            elif direction == "Down":
                king_x += 1
            elif direction == "Down-Right":
                king_x += 1
                king_y += 1
            elif direction == "Down-Left":
                king_x += 1
                king_y -= 1
            elif direction == "Up-Left":
                king_x -= 1
                king_y -= 1
            elif direction == "Up-Right":
                king_x -= 1
                king_y += 1
            else:
                # Should never happen
                break

            # Move queen to the right along the top row
            if queen_x == 1:
                queen_y += 1
            else:
                queen_x = 1
                queen_y = 1

            print(f"{queen_x} {queen_y}")
            sys.stdout.flush()

if __name__ == "__main__":
    solve()
"}

