import math

def distance(p1, p2):
    return math.sqrt((p1[0] - p2[0])**2 + (p1[1] - p2[1])**2)

def solve():
    data = []
    n = int(input())
    for _ in range(n):
        x, y, f = map(int, input().split())
        data.append((x, y, f))

    # dp[i] = max happiness ending at city i (0-indexed)
    dp = [0] * n
    dp[0] = data[0][2]  # start at city 0

    for i in range(1, n):
        dp[i] = data[i][2]  # just visit city i directly
        for j in range(i):
            # go from city j to city i
            dist = distance(data[j], data[i])
            dp[i] = max(dp[i], dp[j] + data[i][2] - dist)

    print(f"{dp[n-1]:.6f}")

solve()
