def generate_unique_permutations(digits):
    """Generate all unique permutations of digits"""
    digits = list(digits)
    n = len(digits)

    # Sort digits
    digits.sort()

    # Use a set to store unique permutations
    permutations = set()

    # Use a recursive approach to generate permutations
    def backtrack(path, used):
        if len(path) == n:
            permutations.add(''.join(path))
            return

        for i in range(n):
            if not used[i]:
                # Skip duplicate digits
                if i > 0 and digits[i] == digits[i - 1] and not used[i - 1]:
                    continue

                used[i] = True
                path.append(digits[i])
                backtrack(path, used)
                path.pop()
                used[i] = False

    backtrack([], [False] * n)
    return sorted(permutations)

T = int(input())
for _ in range(T):
    N = input().strip()
    digits = list(N)
    n = len(digits)

    if n < 3:
        print("Not possible!")
    else:
        permutations = generate_unique_permutations(digits)

        if len(permutations) < 3:
            print("Not possible!")
        else:
            third_smallest = permutations[2]
            third_largest = permutations[-3]
            print(f"{third_smallest} {third_largest}")
