class UnionFind:
    def __init__(self, n):
        self.parent = list(range(n + 1))

    def find(self, x):
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def union(self, x, y):
        px = self.find(x)
        py = self.find(y)
        if px != py:
            self.parent[py] = px


def solve():
    import sys
    input = sys.stdin.read
    data = input().split()

    if not data:
        return

    idx = 0
    n = int(data[idx]); idx += 1
    m1 = int(data[idx]); idx += 1
    m2 = int(data[idx]); idx += 1

    # Find connected components in Mocha's forest
    uf1 = UnionFind(n)
    for _ in range(m1):
        u = int(data[idx]); idx += 1
        v = int(data[idx]); idx += 1
        uf1.union(u, v)

    # Find connected components in Diana's forest
    uf2 = UnionFind(n)
    for _ in range(m2):
        u = int(data[idx]); idx += 1
        v = int(data[idx]); idx += 1
        uf2.union(u, v)

    # For each node, find its component in both forests
    comp1 = {}
    comp2 = {}
    for i in range(1, n + 1):
        comp1[i] = uf1.find(i)
        comp2[i] = uf2.find(i)

    # Group nodes by component in Mocha's forest
    comp_nodes1 = {}
    for i in range(1, n + 1):
        c = comp1[i]
        if c not in comp_nodes1:
            comp_nodes1[c] = []
        comp_nodes1[c].append(i)

    # Group nodes by component in Diana's forest
    comp_nodes2 = {}
    for i in range(1, n + 1):
        c = comp2[i]
        if c not in comp_nodes2:
            comp_nodes2[c] = []
        comp_nodes2[c].append(i)

    # For each component in Mocha's forest, find which components in Diana's forest it intersects with
    comp_intersect = {}
    for c1, nodes in comp_nodes1.items():
        intersect = set()
        for node in nodes:
            c2 = comp2[node]
            intersect.add(c2)
        comp_intersect[c1] = intersect

    # Find all components in both forests
    all_comps = set(comp1.values()) | set(comp2.values())

    # Sort components by size (for greedy approach)
    comp_sizes = {}
    for c in all_comps:
        comp_sizes[c] = len(comp_nodes1.get(c, []))

    # Sort components by size (largest first)
    sorted_comps = sorted(all_comps, key=lambda x: comp_sizes[x], reverse=True)

    # Greedy approach: connect largest component to smallest component
    result = []
    used = set()

    for c in sorted_comps:
        if c in used:
            continue

        nodes = comp_nodes1[c]
        if not nodes:
            continue

        # Find the smallest component that hasn't been used
        smallest = None
        for comp in sorted_comps:
            if comp not in used:
