import sys
sys.setrecursionlimit(10000)

def find_cycle(graph, n):
    """Find a directed cycle in the graph"""
    visited = [False] * (n + 1)
    recursion_stack = [False] * (n + 1)
    cycle = []

    def dfs(v, path):
        if recursion_stack[v]:
            # Found a cycle
            idx = path.index(v)
            cycle.extend(path[idx:])
            return True
        if visited[v]:
            return False

        visited[v] = True
        recursion_stack[v] = True
        path.append(v)

        for neighbor in graph[v]:
            if dfs(neighbor, path):
                return True

        recursion_stack[v] = False
        path.pop()
        return False

    for v in range(1, n + 1):
        if not visited[v]:
            if dfs(v, []):
                return cycle

    return None

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    m = int(next(it))

    graph = [[] for _ in range(n + 1)]
    for _ in range(m):
        a = int(next(it))
        b = int(next(it))
        graph[a].append(b)

    cycle = find_cycle(graph, n)

    if not cycle:
        print(-1)
    else:
        print(len(cycle))
        for v in cycle:
            print(v)

if __name__ == "__main__":
    main()
"}

