    """Compute the sign-variable sum for range [l, r]"""
    # Convert to 0-indexed
    l -= 1
    r -= 1

    # The sign alternates: +, -, +, -, ...
    # For position i (0-indexed), sign = 1 if i % 2 == 0 else -1
    sign = 1 if (l % 2 == 0) else -1

    total = 0
    for i in range(l, r + 1):
        if s[i] == '+':
            total += sign
        else:
            total -= sign
        # Flip sign for next position
        sign *= -1
    return total

def find_opposite_sign(s, l, r):
    """Find a rod with opposite sign in range [l, r]"""
    l -= 1
    r -= 1

    # The sign alternates: +, -, +, -, ...
    # For position i (0-indexed), sign = 1 if i % 2 == 0 else -1
    sign = 1 if (l % 2 == 0) else -1

    for i in range(l, r + 1):
        if s[i] == '+':
            if sign == -1:
                return i + 1  # Convert back to 1-indexed
        else:
            if sign == 1:
                return i + 1
        # Flip sign for next position
        sign *= -1
    return None  # Should never happen if S is odd

def find_same_sign(s, l, r):
    """Find two rods with the same sign in range [l, r]"""
    l -= 1
    r -= 1

    # The sign alternates: +, -, +, -, ...
    # For position i (0-indexed), sign = 1 if i % 2 == 0 else -1
    sign = 1 if (l % 2 == 0) else -1

    first = None
    second = None

    for i in range(l, r + 1):
        if s[i] == '+':
            if sign == 1:
                if first is None:
                    first = i + 1
                else:
                    second = i + 1
                    break
        else:
            if sign == -1:
                if first is None:
                    first = i + 1
                else:
                    second = i + 1
                    break
        # Flip sign for next position
        sign *= -1
    return first, second

def solve():
    import sys
    input = sys.stdin.read().split()
    data = iter(input)

    t = int(next(data))

    for _ in range(t):
        n = int(next(data))
        q = int(next(data))
        s = next(data)

        # Process queries
        print(n)
        for _ in range(q):
            l = int(next(data))
            r = int(next(data))

            # Compute sign-variable sum
            sign = 1 if ((l - 1) % 2 == 0) else -1
            total = 0
            for i in range(l - 1, r):
                if s[i] == '+':
                    total += sign
                else:
                    total -= sign
                sign *= -1

            if total == 0:
                print(0)
            elif total % 2 == 1:
                # Need 1 removal
                pos = find_opposite_sign(s, l, r)
                print(1)
                print(pos)
            else:
                # Need 2 removals
                first, second = find_same_sign(s, l, r)
                print(2)
                print(first, second)

solve()
