        for i in range(n - length + 1):
            substr = s[i:i+length]
            if substr in substrings:
                # Found two identical substrings
                l1, r1 = substrings[substr]
                l2, r2 = i + 1, i + length
                print(f"{l1} {r1} {l2} {r2}")
                found = True
                break
            else:
                substrings[substr] = (i + 1, i + length)

        if not found:
            # Try to find a substring and then a longer substring that starts with it
            # Try all possible starting positions
            for i in range(n - length + 1):
                substr = s[i:i+length]
                # Check if there's a longer substring starting with substr
                for j in range(i + length, n - length + 1):
                    if s[j:j+length].startswith(substr):
                        print(f"{i+1} {i+length} {j+1} {j+length}")
                        found = True
                        break
                if found:
                    break

