def lcs(s1, s2):
    """Length of longest common subsequence"""
    m, n = len(s1), len(s2)
    dp = [[0] * (n + 1) for _ in range(m + 1)]
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if s1[i-1] == s2[j-1]:
                dp[i][j] = dp[i-1][j-1] + 1
            else:
                dp[i][j] = max(dp[i-1][j], dp[i][j-1])
    return dp[m][n]

def shortest_common_supersequence(s1, s2):
    """Length of shortest common supersequence"""
    return len(s1) + len(s2) - lcs(s1, s2)

def solve():
    while True:
        n = int(input())
        if n == 0:
            break

        cities = [input().strip() for _ in range(n)]

        # dp[mask] = (shortest_length, best_string)
        dp = {}
        dp[0] = (0, "")

        for mask in range(1 << n):
            if mask not in dp:
                continue

            length, current = dp[mask]

            for i in range(n):
                if not (mask & (1 << i)):
                    # Try to add city i
                    new_mask = mask | (1 << i)
                    overlap = lcs(current, cities[i])
                    new_length = length + len(cities[i]) - overlap
                    new_string = ""

                    # Build the shortest common supersequence
                    i1, i2 = 0, 0
                    while i1 < len(current) or i2 < len(cities[i]):
                        if i1 < len(current) and i2 < len(cities[i]) and current[i1] == cities[i][i2]:
                            new_string += current[i1]
                            i1 += 1
                            i2 += 1
                        elif i1 < len(current):
                            new_string += current[i1]
                            i1 += 1
                        else:
                            new_string += cities[i][i2]
                            i2 += 1

                    if new_mask not in dp or new_length < dp[new_mask][0]:
                        dp[new_mask] = (new_length, new_string)

        print(dp[(1 << n) - 1][0] if (1 << n) - 1 in dp else 0)

solve()
