import heapq

def dijkstra(n, graph, start):
    dist = [float('inf')] * (n + 1)
    dist[start] = 0
    prev = [None] * (n + 1)

    heap = [(0, start)]

    while heap:
        d, u = heapq.heappop(heap)
        if d > dist[u]:
            continue
        for v, w, idx in graph[u]:
            if dist[v] > dist[u] + w:
                dist[v] = dist[u] + w
                prev[v] = (u, idx)
                heapq.heappush(heap, (dist[v], v))

    return dist, prev

def solve():
    n, m = map(int, input().split())

    graph = [[] for _ in range(n + 1)]
    edges = []

    for idx in range(1, m + 1):
        x, y, z = map(int, input().split())
        edges.append((x, y, z))
        graph[x].append((y, 1, idx))
        graph[y].append((x, 1, idx))

    dist, prev = dijkstra(n, graph, 1)

    # Find the shortest path
    path = []
    current = n
    while current != 1:
        u, idx = prev[current]
        path.append((u, current, idx))
        current = u

    path.reverse()

    # Count affected roads
    affected = []
    for u, v, idx in path:
        for i, (x, y, z) in enumerate(edges):
            if (x == u and y == v) or (x == v and y == u):
                if z == 0:
                    affected.append((u, v, 1))
                break

    for i, (x, y, z) in enumerate(edges):
        if not any((x == u and y == v) or (x == v and y == u) for u, v, idx in path):
            if z == 1:
                affected.append((x, y, 0))

    print(len(affected))
    for x, y, z in affected:
        print(x, y, z)

solve()
