n = int(input())
a = list(map(int, input().split()))
edges = [[] for _ in range(n)]
for _ in range(n - 1):
    x, y = map(int, input().split())
    edges[x - 1].append(y - 1)
    edges[y - 1].append(x - 1)

# Sort vertices by value
vertices = sorted(range(n), key=lambda i: a[i])

# DSU for counting paths with maximum value
parent = list(range(n))
def find(u):
    while parent[u] != u:
        parent[u] = parent[parent[u]]
        u = parent[u]
    return u

def union(u, v):
    pu, pv = find(u), find(v)
    if pu != pv:
        parent[pu] = pv

max_count = [0] * n
for i in range(n):
    v = vertices[i]
    for neighbor in edges[v]:
        if find(neighbor) != find(v):
            union(neighbor, v)
            max_count[v] += 1

# DSU for counting paths with minimum value
parent = list(range(n))
def find(u):
    while parent[u] != u:
        parent[u] = parent[parent[u]]
        u = parent[u]
    return u

def union(u, v):
    pu, pv = find(u), find(v)
    if pu != pv:
        parent[pu] = pv

min_count = [0] * n
for i in range(n - 1, -1, -1):
    v = vertices[i]
    for neighbor in edges[v]:
        if find(neighbor) != find(v):
            union(neighbor, v)
            min_count[v] += 1

result = 0
for i in range(n):
    result += (max_count[i] - min_count[i]) * a[i]

print(result)
